function resultFor(area){const ids=selectedPriority(),hits=ids.map((id)=>Number(meets(area,id))),rent=legalRentFor(area),housingIncluded=Boolean(state.legalDongRent),housingHit=housingIncluded&&Number(rent?.budget?.matched_count||0)>0?1:0;return {area,hits,met:hits.reduce((a,b)=>a+b,0)+housingHit,total:ids.length+Number(housingIncluded),totalFacilities:ids.reduce((sum,id)=>sum+estimate(area,id),0),housing:rent?.budget||null,housingHit:Boolean(housingHit)};}
function ranking(){return areas().map(resultFor).sort((a,b)=>b.met-a.met||Number(b.housing?.matched_count||0)-Number(a.housing?.matched_count||0)||b.totalFacilities-a.totalFacilities||a.area.name.localeCompare(b.area.name,"ko"));}
