function renderRecommendationStep(){const ids=selectedPriority(),isResults=state.recommendationStep===2,ready=ids.length>0;$("recommendation-step-1").hidden=isResults;$("recommendation-step-1").classList.toggle("active",!isResults);$("recommendation-step-2").hidden=!isResults;$("recommendation-step-2").classList.toggle("active",isResults);document.querySelectorAll("[data-progress-step]").forEach((item)=>{const step=Number(item.dataset.progressStep);item.classList.toggle("active",step===state.recommendationStep);item.classList.toggle("complete",step<state.recommendationStep);});const next=$("show-results");next.disabled=!ready;next.querySelector("span").textContent=ready?`${ids.length}개 생활시설 + 주거비로 결과 보기`:"생활 조건을 먼저 선택해 주세요";$("result-summary-copy").textContent=ready?`${ids.map((id)=>CATEGORY_META[id].label).join(" · ")} 시설과 ${housingSelectionLabel()} 조건을 함께 비교했습니다.`:"선택한 생활 조건과 주거비를 기준으로 시흥의 동네를 비교했습니다.";}
