function bindServiceGuides(){document.querySelectorAll("[data-service-guide]").forEach((card)=>{card.addEventListener("click",()=>openServiceGuide(card.dataset.serviceGuide));card.addEventListener("keydown",(event)=>{if(event.key!=="Enter"&&event.key!==" ")return;event.preventDefault();openServiceGuide(card.dataset.serviceGuide);});});$("service-guide-close").addEventListener("click",()=>$("service-guide-dialog").close());$("service-guide-prev").addEventListener("click",()=>moveServiceGuide(-1));$("service-guide-next").addEventListener("click",()=>moveServiceGuide(1));$("service-guide-dialog").addEventListener("click",(event)=>{if(event.target===$("service-guide-dialog"))$("service-guide-dialog").close();});}
function bindControls(){document.querySelectorAll("[data-page-link]").forEach((link)=>link.addEventListener("click",(event)=>{event.preventDefault();showPage(link.dataset.pageLink);}));$("mobile-menu").addEventListener("click",()=>{const open=document.querySelector(".topbar").classList.toggle("menu-open");$("mobile-menu").setAttribute("aria-expanded",String(open));});window.addEventListener("popstate",()=>showPage(location.hash.slice(1),false));$("address-form").addEventListener("submit",(event)=>{event.preventDefault();openPostcode("address");});$("result-address-form").addEventListener("submit",(event)=>{event.preventDefault();openPostcode("result");});$("address-filter-reset").addEventListener("click",()=>{state.addressSelected.clear();state.addressVisibleCount={};renderAddressCategories();renderAddressResults();});document.querySelectorAll("#address-walk-segment button,#result-walk-segment button").forEach((button)=>button.addEventListener("click",()=>{state.addressMinutes=Number(button.dataset.minutes);state.addressVisibleCount={};render();renderAddressMap();renderMap();}));$("reset-selection").addEventListener("click",resetRecommendation);$("summary-reset").addEventListener("click",resetRecommendation);document.querySelectorAll("[data-housing-type]").forEach((button)=>button.addEventListener("click",()=>{const presets={monthly:{primary:[30,100],deposit:[500,5000]},jeonse:{deposit:[10000,40000]}},preset=presets[button.dataset.housingType];state.housingType=button.dataset.housingType;if(preset.primary)[state.budgetMin,state.budgetMax]=preset.primary;if(preset.deposit)[state.depositMin,state.depositMax]=preset.deposit;renderBudget();scheduleLegalRentLoad();}));[["budget-min","budgetMin","budgetMax"],["budget-max","budgetMax","budgetMin"],["budget-min-input","budgetMin","budgetMax"],["budget-max-input","budgetMax","budgetMin"],["deposit-min","depositMin","depositMax"],["deposit-max","depositMax","depositMin"],["deposit-min-input","depositMin","depositMax"],["deposit-max-input","depositMax","depositMin"]].forEach(([id,key,otherKey])=>$(id).addEventListener(id.includes("input")?"change":"input",(event)=>{const maximum=Number(event.target.max),value=Math.min(maximum,Math.max(0,Number(event.target.value)||0));state[key]=value;const isMinimum=key.endsWith("Min");if(isMinimum&&state[key]>state[otherKey])state[otherKey]=state[key];if(!isMinimum&&state[key]<state[otherKey])state[otherKey]=state[key];renderBudget();scheduleLegalRentLoad();}));$("show-results").addEventListener("click",()=>goToRecommendationStep(2));$("back-to-conditions").addEventListener("click",()=>goToRecommendationStep(1));$("criteria-button").addEventListener("click",()=>$("criteria-dialog").showModal());document.querySelector(".dialog-close").addEventListener("click",()=>$("criteria-dialog").close());$("area-brief-dialog").querySelector(".area-brief-close").addEventListener("click",()=>$("area-brief-dialog").close());$("area-brief-dialog").addEventListener("click",(event)=>{if(event.target===$("area-brief-dialog"))$("area-brief-dialog").close();});$("show-facilities-on-map").addEventListener("click",()=>{state.recommendationStep=2;showPage("map");renderRecommendationStep();});$("map-zoom-in").addEventListener("click",()=>state.naverMap?.setZoom(state.naverMap.getZoom()+1,true));$("map-zoom-out").addEventListener("click",()=>state.naverMap?.setZoom(state.naverMap.getZoom()-1,true));$("map-fullscreen").addEventListener("click",()=>document.querySelector(".map-canvas").requestFullscreen());document.querySelectorAll("[data-map-mode]").forEach((button)=>button.addEventListener("click",()=>{state.mapMode=button.dataset.mapMode;document.querySelectorAll("[data-map-mode]").forEach((item)=>item.classList.toggle("active",item===button));renderMap();}));$("route-dialog-close").addEventListener("click",()=>$("route-dialog").close());$("route-dialog").addEventListener("click",(event)=>{if(event.target===$("route-dialog"))$("route-dialog").close();});}
async function init(){try{const response=await fetch("/api/infrastructure");if(!response.ok)throw new Error("생활 인프라 데이터를 불러오지 못했습니다.");state.data=await response.json();const received=new Map(state.data.categories.map((category)=>[category.id,category]));state.data.categories=FINAL_CATEGORIES.map((category)=>({...received.get(category.id),...category}));state.data.categories.forEach((category)=>{const group=GROUP_META[categoryGroup(category)]||GROUP_META.daily;CATEGORY_META[category.id]={...group,...CATEGORY_META[category.id],label:category.label,icon:CATEGORY_ICONS[category.id]||CATEGORY_META[category.id]?.icon||group.icon,color:group.color,density_only:Boolean(category.density_only)};});const [housingResponse,legalRentResponse,configResponse]=await Promise.all([fetch("/api/housing-costs"),fetch(`/api/legal-dong-rent?${legalRentQuery()}`),fetch("/api/config")]);if(housingResponse.ok)state.housingData=await housingResponse.json();if(legalRentResponse.ok)state.legalDongRent=await legalRentResponse.json();else state.housingError=(await legalRentResponse.json()).detail||"법정동별 전월세 데이터를 불러오지 못했습니다.";const config=await configResponse.json();state.naverKey=config.naver_maps_key_id||"";state.serverKakaoReady=Boolean(config.kakao_rest_ready);await loadBoundaries();bindControls();bindReportExportControls();bindKakaoKeyForm();window.addEventListener("scroll",updateFloatingSidebar,{passive:true});window.addEventListener("resize",updateFloatingSidebar,{passive:true});render();showPage(location.hash.slice(1)||"home",false);updateFloatingSidebar();}catch(error){document.body.innerHTML=`<main class="fatal"><h1>서비스를 불러오지 못했습니다.</h1><p>${escapeHtml(error.message)}</p></main>`;}}
bindNeighborhoodMenu();
bindServiceGuides();
init();
